List<PoseSample> runUpAwayCapture() {
  PosePoint? at(List<num> row, int index) => row[index] < 0
      ? null
      : PosePoint(row[index].toDouble(), row[index + 1].toDouble());

  return [
    for (final row in _rows)
      if (row.length == 1)
        PoseSample(timestamp: Duration(milliseconds: row[0].toInt()))
      else
        PoseSample(
          timestamp: Duration(milliseconds: row[0].toInt()),
          foot: PosePoint(row[1].toDouble(), row[2].toDouble()),
          footY: row[2].toDouble(),
          torsoPixels: row[3].toDouble(),
          leftAnkle: at(row, 4),
          rightAnkle: at(row, 6),
          leftKnee: at(row, 8),
          rightKnee: at(row, 10),
          leftHip: at(row, 12),
          rightHip: at(row, 14),
          leftShoulder: at(row, 16),
          rightShoulder: at(row, 18),
          leftWrist: at(row, 20),
          rightWrist: at(row, 22),
        ),
  ];
}
